/// Repeatedly apply `parser`, starting from an initializer produced by `init`,
/// and fold each successful result with `fold`. Requires at least one successful parse.
/// Returns an error if the first parse fails or if the parser would consume zero input
/// (to avoid infinite loops).
pub fn fold_many1<I, O, E, P, Acc, InitFn, FoldFn>(
  mut parser: P,
  init: InitFn,
  fold: FoldFn,
) -> impl FnMut(I) -> IResult<I, Acc, E>
where
  P: Parser<I, O, E>,
  I: Clone + InputLength,
  Acc: Clone,
  InitFn: Fn() -> Acc,
  FoldFn: Fn(Acc, O) -> Acc,
  E: ParseError<I>,
{
