    let mut acc = init();
    let mut consumed = false;

    loop {
      match parser.parse(input.clone()) {
        Ok((next_input, value)) => {
          // Prevent infinite loops: parser must consume input
          if next_input.input_len() == input.input_len() {
            return Err(Err::Error(E::from_error_kind(input, ErrorKind::Fold)));
          }
          acc = fold(acc, value);
          input = next_input;
          consumed = true;
        }
        Err(_) => break,
      }
    }

    if !consumed {
      Err(Err::Error(E::from_error_kind(input, ErrorKind::Fold)))
    } else {
      Ok((input, acc))
    }
  }
